css:
:root {
  background: #F2F2F7;
}

html {
  background: #F2F2F7;
}

html.nightMode,
body.nightMode,
.nightMode {
  background: #000000;
}

.card {
  --page-bg: #F2F2F7;
  --card-bg: #FFFFFF;
  --surface-bg: #F9F9FB;
  --elevated-bg: #F2F2F7;
  --text-primary: #000000;
  --text-secondary: rgba(60, 60, 67, 0.60);
  --text-tertiary: rgba(60, 60, 67, 0.30);
  --separator: rgba(60, 60, 67, 0.18);
  --separator-strong: rgba(60, 60, 67, 0.28);
  --accent-blue: #007AFF;
  --accent-green: #34C759;
  --accent-red: #FF3B30;
  --accent-orange: #FF9500;
  --accent-yellow: #FFCC00;
  --accent-purple: #AF52DE;
  --selection-bg: rgba(0, 122, 255, 0.18);
  --shadow-card: 0 18px 45px rgba(0, 0, 0, 0.10), 0 2px 8px rgba(0, 0, 0, 0.06);
  --radius-card: 22px;
  --radius-large: 14px;
  --radius-medium: 10px;
  --radius-small: 7px;
  --content-width: 760px;

  box-sizing: border-box;
  width: min(calc(100% - 32px), var(--content-width));
  min-height: auto;
  margin: 32px auto;
  padding: 30px 34px;
  color: var(--text-primary);
  background: var(--card-bg);
  border: 0.5px solid var(--separator);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 18px;
  font-weight: 400;
  line-height: 1.62;
  letter-spacing: -0.01em;
  text-align: left;
  word-wrap: break-word;
  overflow-wrap: break-word;
  -webkit-text-size-adjust: 100%;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.nightMode.card,
.nightMode .card {
  --page-bg: #000000;
  --card-bg: #1C1C1E;
  --surface-bg: #242426;
  --elevated-bg: #2C2C2E;
  --text-primary: #FFFFFF;
  --text-secondary: rgba(235, 235, 245, 0.62);
  --text-tertiary: rgba(235, 235, 245, 0.34);
  --separator: rgba(84, 84, 88, 0.65);
  --separator-strong: rgba(99, 99, 102, 0.78);
  --accent-blue: #0A84FF;
  --accent-green: #30D158;
  --accent-red: #FF453A;
  --accent-orange: #FF9F0A;
  --accent-yellow: #FFD60A;
  --accent-purple: #BF5AF2;
  --selection-bg: rgba(10, 132, 255, 0.30);
  --shadow-card: 0 18px 45px rgba(0, 0, 0, 0.40), 0 2px 8px rgba(0, 0, 0, 0.30);

  color: var(--text-primary);
  background: var(--card-bg);
  border-color: var(--separator);
  box-shadow: var(--shadow-card);
}

.card *,
.card *::before,
.card *::after {
  box-sizing: border-box;
}

.card::selection,
.card *::selection {
  background: var(--selection-bg);
}

.apple-shell,
.prettify-flashcard {
  display: block;
  width: 100%;
  max-width: 100%;
  margin: 0;
  padding: 0;
  color: inherit;
  background: transparent;
  border: 0;
  box-shadow: none;
  text-align: left;
}

.apple-meta,
.prettify-card-header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 22px;
  margin: 0 0 14px;
  padding-bottom: 12px;
  border-bottom: 0.5px solid var(--separator);
}

.apple-deck,
.prettify-deck {
  min-width: 0;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.apple-content,
.prettify-field {
  color: var(--text-primary);
  font-size: 1em;
}

.apple-kicker {
  margin: 0 0 0.35em;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.apple-question,
.apple-answer {
  color: var(--text-primary);
}

.apple-panel {
  margin: 1.1em 0 0;
  padding: 14px 16px;
  color: var(--text-primary);
  background: var(--surface-bg);
  border: 0.5px solid var(--separator);
  border-radius: var(--radius-large);
}

.apple-code-panel {
  background: var(--elevated-bg);
}

.apple-code-field {
  display: block;
  margin: 0;
  padding: 16px 18px;
  color: var(--text-primary);
  background: var(--elevated-bg);
  border: 0.5px solid var(--separator);
  border-radius: var(--radius-large);
  font-family: "SF Mono", ui-monospace, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 0.9em;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.apple-output-field {
  background: var(--surface-bg);
}

.apple-io-card {
  text-align: center;
}

.apple-io-header,
.apple-io-footer {
  margin: 0 0 1em;
  color: var(--text-primary);
  text-align: left;
}

.apple-io-footer {
  margin: 1em 0 0;
  color: var(--text-secondary);
}

.apple-io-stage {
  display: flex;
  justify-content: center;
  width: 100%;
  margin: 1em 0;
}

.apple-io-image {
  position: relative;
  display: inline-block;
  max-width: 100%;
  line-height: 0;
  background: var(--elevated-bg);
  border: 0.5px solid var(--separator);
  border-radius: var(--radius-large);
  overflow: hidden;
}

.apple-io-image img {
  display: block;
  max-width: 100%;
  height: auto;
  margin: 0;
  border: 0;
  border-radius: 0;
}

.apple-io-mask {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  line-height: 0;
  pointer-events: none;
}

.apple-io-mask svg,
.apple-io-mask img {
  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  border: 0;
  border-radius: 0;
}

.card h1,
.card h2,
.card h3,
.card h4 {
  margin: 1.2em 0 0.45em;
  color: var(--text-primary);
  font-weight: 650;
  line-height: 1.18;
  letter-spacing: -0.035em;
}

.card h1:first-child,
.card h2:first-child,
.card h3:first-child,
.card h4:first-child {
  margin-top: 0;
}

.card h1 {
  font-size: 2em;
}

.card h2 {
  font-size: 1.55em;
}

.card h3 {
  font-size: 1.25em;
}

.card h4 {
  font-size: 1.06em;
}

.card p {
  margin: 0.75em 0;
}

.card p:first-child {
  margin-top: 0;
}

.card p:last-child {
  margin-bottom: 0;
}

.card small,
.card .hint,
.card .extra,
.card .note,
.card .subtitle,
.card .secondary {
  color: var(--text-secondary);
}

b,
strong {
  color: var(--text-primary);
  font-weight: 650;
}

a {
  color: var(--accent-blue);
  text-decoration: none;
  text-underline-offset: 0.18em;
  -webkit-tap-highlight-color: transparent;
}

a:hover,
a:focus {
  text-decoration: underline;
  text-decoration-thickness: 1px;
}

.cloze {
  color: var(--accent-blue);
  background: rgba(0, 122, 255, 0.12);
  border: 0.5px solid rgba(0, 122, 255, 0.18);
  border-radius: var(--radius-small);
  padding: 0.04em 0.32em;
  font-weight: 650;
  text-decoration: none;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

.nightMode.card .cloze,
.nightMode .card .cloze {
  color: var(--accent-blue);
  background: rgba(10, 132, 255, 0.18);
  border-color: rgba(10, 132, 255, 0.28);
}

hr,
.prettify-divider,
.apple-divider {
  height: 0.5px;
  margin: 1.45em 0;
  background: var(--separator);
  border: 0;
}

ul,
ol {
  margin: 0.78em 0 0.78em 1.35em;
  padding: 0;
}

li {
  margin: 0.38em 0;
  padding-left: 0.2em;
}

li > ul,
li > ol {
  margin-top: 0.28em;
  margin-bottom: 0.28em;
}

ul li::marker,
ol li::marker {
  color: var(--accent-blue);
  font-weight: 600;
}

code,
kbd {
  font-family: "SF Mono", ui-monospace, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 0.86em;
  line-height: 1.45;
  color: var(--text-primary);
  background: var(--elevated-bg);
  border: 0.5px solid var(--separator);
  border-radius: var(--radius-small);
}

code {
  padding: 0.13em 0.36em;
  white-space: normal;
  word-break: break-word;
}

kbd {
  display: inline-block;
  min-width: 1.7em;
  padding: 0.12em 0.42em;
  font-weight: 600;
  text-align: center;
  box-shadow: inset 0 -1px 0 var(--separator-strong);
}

pre {
  max-width: 100%;
  margin: 1em 0;
  padding: 16px 18px;
  overflow-x: auto;
  color: var(--text-primary);
  background: var(--elevated-bg);
  border: 0.5px solid var(--separator);
  border-radius: var(--radius-large);
  font-family: "SF Mono", ui-monospace, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 0.86em;
  line-height: 1.48;
  white-space: pre;
  -webkit-overflow-scrolling: touch;
}

pre code {
  display: block;
  padding: 0;
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: 0;
  font-size: 1em;
  line-height: inherit;
  white-space: inherit;
  word-break: normal;
}

blockquote {
  margin: 1em 0;
  padding: 0.8em 1em;
  color: var(--text-secondary);
  background: var(--surface-bg);
  border-left: 3px solid var(--accent-blue);
  border-radius: var(--radius-medium);
}

blockquote p {
  margin: 0.45em 0;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
  margin: 1em auto;
  border: 0.5px solid var(--separator);
  border-radius: var(--radius-large);
}

table {
  width: 100%;
  max-width: 100%;
  margin: 1em 0;
  color: var(--text-primary);
  background: var(--card-bg);
  border: 0.5px solid var(--separator);
  border-collapse: separate;
  border-spacing: 0;
  border-radius: var(--radius-large);
  font-size: 0.94em;
  line-height: 1.45;
  overflow: hidden;
}

thead {
  background: var(--elevated-bg);
}

tbody {
  background: var(--card-bg);
}

th,
td {
  padding: 0.68em 0.78em;
  text-align: left;
  vertical-align: top;
  border-bottom: 0.5px solid var(--separator);
}

th {
  color: var(--text-primary);
  font-weight: 650;
}

tr:last-child th,
tr:last-child td {
  border-bottom: 0;
}

mark {
  color: var(--text-primary);
  background: rgba(255, 204, 0, 0.40);
  border-radius: var(--radius-small);
  padding: 0.04em 0.24em;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

.nightMode.card mark,
.nightMode .card mark {
  background: rgba(255, 214, 10, 0.30);
}

.apple-tags,
.tags,
.prettify-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin: 1.35em 0 0;
  padding-top: 0.95em;
  color: var(--text-secondary);
  border-top: 0.5px solid var(--separator);
  font-size: 12px;
  line-height: 1.35;
}

.tag,
.prettify-tag {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 4px 9px;
  color: var(--text-secondary);
  background: var(--elevated-bg);
  border: 0.5px solid var(--separator);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card .MathJax,
.card mjx-container {
  max-width: 100%;
  color: var(--text-primary);
  overflow-x: auto;
  overflow-y: hidden;
}

@media (max-width: 700px) {
  .card {
    width: calc(100% - 20px);
    margin: 10px auto;
    padding: 22px 20px;
    border-radius: 18px;
    font-size: 17px;
  }

  .card h1 {
    font-size: 1.55em;
  }

  .card h2 {
    font-size: 1.28em;
  }

  pre,
  .apple-code-field {
    padding: 13px 14px;
    font-size: 0.82em;
  }

  table {
    display: block;
    overflow-x: auto;
    white-space: nowrap;
    -webkit-overflow-scrolling: touch;
  }

  th,
  td {
    padding: 0.58em 0.68em;
  }

  ul,
  ol {
    margin-left: 1.2em;
  }
}

@media (max-width: 380px) {
  .card {
    width: calc(100% - 12px);
    margin: 6px auto;
    padding: 20px 16px;
    border-radius: 16px;
    font-size: 16px;
  }
}
